/**
 * POST /api/store/ai/suggestions — "Improve Store" suggestions generated by the
 * real route from the seller's real storefront row; the OpenAI client is mocked.
 */
import { afterAll, beforeAll, beforeEach, describe, expect, it, vi } from "vitest";
import express from "express";
import type { AddressInfo } from "node:net";
import type { Server } from "node:http";
import crypto from "node:crypto";
import { eq } from "drizzle-orm";
import { db, products, storefronts } from "@workspace/db";

const state = vi.hoisted(() => ({
  owner: "",
  aiCalls: [] as Array<{ messages: any[] }>,
  aiReply: null as null | (() => unknown),
}));

vi.mock("@clerk/express", () => ({ getAuth: () => ({ userId: state.owner }), clerkClient: {} }));
vi.mock("../../middlewares/requireAuth", () => ({
  requireAuth: (req: any, _res: any, next: any) => { req.clerkUserId = state.owner; next(); },
}));
vi.mock("../../middlewares/rateLimit", () => ({
  rateLimit: () => (_req: any, _res: any, next: any) => next(),
}));
vi.mock("@workspace/integrations-openai-ai-server", () => ({
  openai: {
    chat: {
      completions: {
        create: async (args: { messages: any[] }) => {
          state.aiCalls.push(args);
          const reply = state.aiReply?.();
          if (reply instanceof Error) throw reply;
          return { choices: [{ message: { content: typeof reply === "string" ? reply : JSON.stringify(reply) } }] };
        },
      },
    },
  },
}));
vi.mock("@workspace/integrations-openai-ai-server/text", () => ({ generateText: vi.fn() }));

state.owner = `sug-${crypto.randomBytes(4).toString("hex")}`;

let server: Server;
let base = "";

async function post(path: string) {
  const res = await fetch(`${base}/api/store/ai${path}`, { method: "POST", headers: { "content-type": "application/json" }, body: "{}" });
  return { status: res.status, body: (await res.json().catch(() => null)) as any };
}

beforeAll(async () => {
  process.env.AI_INTEGRATIONS_OPENAI_API_KEY = "test-key";
  process.env.AI_INTEGRATIONS_OPENAI_BASE_URL = "http://openai.test";
  await db.insert(storefronts).values({
    ownerId: state.owner, slug: `sug-${crypto.randomBytes(4).toString("hex")}`, title: "Nightshift Studio",
    sections: [{ type: "hero_image", settings: { heading: "The new uniform." } }],
    collections: [{ id: "c1", name: "Winter", status: "draft" }],
  });
  await db.insert(products).values({ ownerId: state.owner, name: "Heavyweight Tee", status: "active" });
  const { default: router } = await import("../store-ai");
  const app = express();
  app.use(express.json());
  app.use("/api/store/ai", router);
  server = app.listen(0, "127.0.0.1");
  await new Promise<void>((r) => server.once("listening", r));
  base = `http://127.0.0.1:${(server.address() as AddressInfo).port}`;
});

beforeEach(() => {
  state.aiCalls = [];
  state.aiReply = null;
  process.env.AI_INTEGRATIONS_OPENAI_API_KEY = "test-key";
  process.env.AI_INTEGRATIONS_OPENAI_BASE_URL = "http://openai.test";
});

afterAll(async () => {
  await db.delete(storefronts).where(eq(storefronts.ownerId, state.owner));
  await db.delete(products).where(eq(products.ownerId, state.owner));
  await new Promise<void>((r) => server.close(() => r()));
});

describe("POST /api/store/ai/suggestions", () => {
  it("sends the seller's real store data and returns parsed, actionable suggestions", async () => {
    state.aiReply = () => ({
      suggestions: [
        {
          category: "copy", title: "Add an SEO title", problem: "Search engines see no title.",
          recommendation: "Name what you sell.", action: { type: "set_seo_title", value: "Nightshift Studio — Heavyweight Tees" },
        },
        {
          category: "product", title: "Publish your Winter collection", problem: "Your only collection is a draft.",
          recommendation: "Add products and set it active.", action: { type: "open_screen", screen: "collections" },
        },
        { category: "copy", title: "Broken", problem: "x", recommendation: "y", action: { type: "drop_tables" } },
      ],
    });
    const r = await post("/suggestions");
    expect(r.status).toBe(200);
    expect(r.body.suggestions).toHaveLength(2);
    expect(r.body.suggestions[0].action).toEqual({ type: "set_seo_title", value: "Nightshift Studio — Heavyweight Tees" });
    expect(r.body.suggestions[1].action).toEqual({ type: "open_screen", screen: "collections" });

    const userMsg = String(state.aiCalls[0].messages[1].content);
    expect(userMsg).toContain("Nightshift Studio");
    expect(userMsg).toContain("Heavyweight Tee");
    expect(userMsg).toContain("The new uniform.");
  });

  it("returns 503 ai_unavailable when AI is not configured (no canned fallback)", async () => {
    delete process.env.AI_INTEGRATIONS_OPENAI_API_KEY;
    const r = await post("/suggestions");
    expect(r.status).toBe(503);
    expect(r.body.code).toBe("ai_unavailable");
    expect(state.aiCalls).toHaveLength(0);
  });

  it("returns 502 when the model fails or returns nothing usable", async () => {
    state.aiReply = () => new Error("boom");
    expect((await post("/suggestions")).status).toBe(502);
    state.aiReply = () => ({ suggestions: [{ title: "no fields" }] });
    const r = await post("/suggestions");
    expect(r.status).toBe(502);
    expect(r.body.code).toBe("ai_failed");
  });
});
